={
  "model": "llama-3.1-8b-instant",
  "max_tokens": 300,
  "messages": [
    {
      "role": "system",
      "content": "You are a professional certificate copy writer. Generate warm, personalised certificate body text. Return ONLY the certificate body paragraph — no headings, no extra text, no quotes."
    },
    {
      "role": "user",
      "content": "Write a 2-3 sentence professional yet warm certificate body for:\n\nStudent Name: {{ $('Receive Course Completion Event').item.json.body.student_name }}\nCourse: {{ $('Lookup Course Pass Threshold').item.json.course_title }}\nScore Achieved: {{ $('Receive Course Completion Event').item.json.body.score }}%\nCompletion Date: {{ $('Receive Course Completion Event').item.json.body.completion_date }}\nCertificate Type: {{ $('Lookup Course Pass Threshold').item.json.certificate_template }}\n\nMention the score and date naturally. No headings, no quotes."
    }
  ]
}

parameters.jsCode:
// Extract AI-generated certificate text (Groq uses OpenAI-compatible format)
const aiResponse = $input.item.json;
const personalizedText = aiResponse.choices[0].message.content.trim();

// Pull original data
const webhookData = $('Receive Course Completion Event').item.json.body;
const sheetData = $('Lookup Course Pass Threshold').item.json;

// Format date nicely
const rawDate = webhookData.completion_date;
const formatted = new Date(rawDate).toLocaleDateString('en-IN', {
  day: 'numeric', month: 'long', year: 'numeric'
});

// Generate a unique certificate ID
const certId = `CERT-${webhookData.course_id}-${webhookData.student_id}-${Date.now()}`;

// Build the HTML certificate
const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700&family=Inter:wght@300;400;600&display=swap');
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: 'Inter', sans-serif;
    background: #f9f6f0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    padding: 40px;
  }
  .certificate {
    background: #ffffff;
    border: 2px solid #c9a84c;
    border-radius: 8px;
    padding: 60px 80px;
    max-width: 860px;
    width: 100%;
    text-align: center;
    box-shadow: 0 4px 30px rgba(0,0,0,0.08);
    position: relative;
  }
  .certificate::before, .certificate::after {
    content: '';
    position: absolute;
    top: 12px; left: 12px; right: 12px; bottom: 12px;
    border: 1px solid #e8d5a3;
    border-radius: 4px;
    pointer-events: none;
  }
  .org-name {
    font-family: 'Inter', sans-serif;
    font-weight: 600;
    font-size: 13px;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: #888;
    margin-bottom: 32px;
  }
  .title {
    font-family: 'Playfair Display', serif;
    font-size: 42px;
    font-weight: 700;
    color: #1a1a2e;
    margin-bottom: 12px;
    line-height: 1.2;
  }
  .subtitle {
    font-size: 13px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #c9a84c;
    margin-bottom: 36px;
  }
  .presented-to {
    font-size: 15px;
    color: #666;
    margin-bottom: 12px;
  }
  .student-name {
    font-family: 'Playfair Display', serif;
    font-size: 38px;
    color: #1a1a2e;
    border-bottom: 2px solid #c9a84c;
    display: inline-block;
    padding-bottom: 8px;
    margin-bottom: 36px;
  }
  .body-text {
    font-size: 15px;
    line-height: 1.8;
    color: #444;
    max-width: 600px;
    margin: 0 auto 36px;
  }
  .course-name {
    font-weight: 700;
    color: #1a1a2e;
  }
  .meta-row {
    display: flex;
    justify-content: center;
    gap: 60px;
    margin-bottom: 48px;
  }
  .meta-item {
    text-align: center;
  }
  .meta-label {
    font-size: 10px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #999;
    margin-bottom: 4px;
  }
  .meta-value {
    font-size: 16px;
    font-weight: 600;
    color: #1a1a2e;
  }
  .footer {
    border-top: 1px solid #eee;
    padding-top: 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .cert-id {
    font-size: 10px;
    color: #bbb;
    letter-spacing: 1px;
  }
  .badge {
    background: #c9a84c;
    color: white;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 6px 16px;
    border-radius: 20px;
  }
</style>
</head>
<body>
<div class="certificate">
  <div class="org-name">YourOrg Academy</div>
  <div class="title">Certificate of Completion</div>
  <div class="subtitle">of Achievement</div>
  <div class="presented-to">This certificate is proudly presented to</div>
  <div class="student-name">${webhookData.student_name}</div>
  <div class="body-text">${personalizedText}</div>
  <div class="meta-row">
    <div class="meta-item">
      <div class="meta-label">Course</div>
      <div class="meta-value course-name">${sheetData.course_title}</div>
    </div>
    <div class="meta-item">
      <div class="meta-label">Score</div>
      <div class="meta-value">${webhookData.score}%</div>
    </div>
    <div class="meta-item">
      <div class="meta-label">Date</div>
      <div class="meta-value">${formatted}</div>
    </div>
  </div>
  <div class="footer">
    <div class="cert-id">ID: ${certId}</div>
    <div class="badge">Verified ✓</div>
    <div class="cert-id">${webhookData.student_email}</div>
  </div>
</div>
</body>
</html>`;

return {
  html,
  certId,
  studentName: webhookData.student_name,
  studentEmail: webhookData.student_email,
  courseName: sheetData.course_title,
  score: webhookData.score,
  completionDate: formatted,
  personalizedText
};
